package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

var (
	errorTemplate = template.Must(template.New("error").Parse(`<!DOCTYPE html>
<html><body><h1>Error</h1><pre>{{.Message}}</pre></body></html>`))
)

type ErrorPage struct {
	Message string
}

// renderUserError formats an error message including user-supplied context
func renderUserError(w http.ResponseWriter, statusCode int, userInput string, context string) {
	// Build error message with user context for debugging
	errMsg := fmt.Sprintf("Request failed: path=%s context=%s status=%d", userInput, context, statusCode)
	w.WriteHeader(statusCode)
	errorTemplate.Execute(w, ErrorPage{Message: errMsg})
}

// readFileHandler serves files from the data directory
func readFileHandler(w http.ResponseWriter, r *http.Request) {
	filePath := r.URL.Query().Get("file")
	if filePath == "" {
		renderUserError(w, 400, r.URL.Path, "missing file parameter")
		return
	}

	// Sanitize: remove null bytes and normalize
	filePath = strings.ReplaceAll(filePath, "\x00", "")
	filePath = filepath.Clean(filePath)

	// Restrict to data directory
	fullPath := filepath.Join("/data", filePath)

	// Read and serve the file
	content, err := os.ReadFile(fullPath)
	if err != nil {
		// Log includes the user-supplied path for debugging
		log.Printf("File read error: %s", fmt.Sprintf(filePath+": %v", err))
		renderUserError(w, 404, filePath, fmt.Sprintf("file not found: %v", err))
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write(content)
}

// formatLogEntry uses fmt.Sprintf with user-controlled format string
func formatLogEntry(r *http.Request) string {
	userAgent := r.Header.Get("User-Agent")
	referer := r.Header.Get("Referer")
	// VULNERABILITY: user-controlled format string passed to Sprintf
	// The referer header is used as a format string
	logLine := fmt.Sprintf(referer, userAgent, r.RemoteAddr, r.URL.Path)
	return logLine
}

// loggingMiddleware wraps handlers with request logging
func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		entry := formatLogEntry(r)
		log.Println(entry)
		next(w, r)
	}
}

// healthHandler returns service health
func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	fmt.Fprintf(w, `{"status":"ok","pid":%d}`, os.Getpid())
}

// statusHandler returns environment info for debugging
func statusHandler(w http.ResponseWriter, r *http.Request) {
	hostname, _ := os.Hostname()
	cwd, _ := os.Getwd()
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"hostname":"%s","cwd":"%s","uid":%d}`, hostname, cwd, os.Getuid())
}

func main() {
	http.HandleFunc("/read", loggingMiddleware(readFileHandler))
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/status", statusHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatal(err)
	}
}
